mapper.select:
SELECT paid_fen, refunded_fen, refund_reserved_fen
FROM vi_payment_order
WHERE id = #{paymentId}

SELECT *
FROM vi_refund_order
WHERE case_id = #{caseId}
    AND review_revision = #{revision}

SELECT order_id
FROM vi_payment_order
WHERE id = #{paymentId}

SELECT decision,approved_fen,return_required
FROM vi_aftersale_review
WHERE case_id = #{caseId}
    AND revision = #{revision}

mapper.update:
UPDATE vi_payment_order
SET refund_reserved_fen = refund_reserved_fen - #{amount},
    refunded_fen = refunded_fen + #{amount}0,
    version = version + 1,updated_at = UTC_TIMESTAMP(3)
WHERE id = #{paymentId}
    AND refund_reserved_fen >= #{amount}
    AND paid_fen >= refunded_fen + #{amount}

mapper.select:
SELECT *
FROM vi_payment_reconciliation
WHERE kind = #{kind}
    AND subject_id = #{subjectId}
FOR UPDATE

mapper.update:
UPDATE vi_payment_reconciliation
SET status = 'OPEN',local_status = #{localStatus},channel_status = #{channelStatus},reason_code = #{reasonCode},
    verified_at = NULL,resolved_at = NULL,resolved_by = NULL,
    version = version + 1,updated_at = UTC_TIMESTAMP(3)
WHERE id = #{id}
    AND version = #{version}

UPDATE vi_payment_reconciliation
SET status = 'CHECKING',local_status = #{localStatus},channel_status = #{channelStatus},
    verified_at = #{verifiedAt,typeHandler=com.xinyi.rongli.platform.mybatis.ViUtcInstantTypeHandler},
    version = version + 1,updated_at = UTC_TIMESTAMP(3)
WHERE id = #{id}
    AND version = #{version}

mapper.sql:
FROM vi_payment_reconciliation c
JOIN vi_payment_order p ON p.id = c.payment_id
WHERE p.order_id = c.order_id

    AND c.id = #{query.caseId}


    AND EXISTS (
        SELECT 1 FROM vi_order o
        WHERE o.id = c.order_id AND o.order_no = #{query.orderNo}
    )


    AND c.kind = #{query.type}


    AND c.status = #{query.status}




            AND p.receiver_dept_id IN

                #{d}



            AND 1 = 0

mapper.select:
SELECT c.*

ORDER BY c.id DESC
LIMIT #{size} OFFSET #{offset}
